{"source":"#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAXN 100000

struct Angle {
    long double val;
    int ind;
};

typedef struct Angle Angle;

int compare(const void *s, const void *t) {
    long double a = ((Angle*)s)->val;
    long double b = ((Angle*)t)->val;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}


int main(int argc, char *argv[]) {
    int n, x, y;
    Angle angle[MAXN];
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &x, &y);
        angle[i].ind = i+1;
        angle[i].val = atan2l((long double)y, (long double)x);
    }
    qsort(angle, n, sizeof(Angle), compare);
    int a = angle[n-1].ind, b = angle[0].ind;
    long double min = 2*acosl(-1.0) - (angle[n-1].val - angle[0].val);
    for (int i = 0; i < n-1; ++i) {
        if (angle[i+1].val - angle[i].val < min) {
            min = angle[i+1].val - angle[i].val;
            a = angle[i].ind;
            b = angle[i+1].ind;
        }
    }
    printf("%d %d\n", a, b);
}"}
